import numpy as np, pandas as pd, glob, os
log = pd.read_csv('data/run_log.csv')
bad=[]
for _,r in log.iterrows():
    f=f"data/raw/{r.date}/run_{r.run_id:03d}.csv"
    if '2026-03' in f:
        d=pd.read_csv(f,sep=';'); d.columns=['t','V']
    else:
        d=pd.read_csv(f,comment='#'); d.columns=['t','V']
    dt=np.diff(d.t.values)
    issues=[]
    if not np.all(np.isfinite(d.V)): issues.append('nan')
    if d.t.is_monotonic_increasing is False: issues.append('time')
    if np.any(dt<=0): issues.append('dt<=0')
    if abs(np.median(dt)-0.005)>1e-6: issues.append('fs')
    if d.V.max()>4.9 or d.V.min()<0.1: issues.append('range')
    if len(d)!=2400 and len(d)!=2401: issues.append('n=%d'%len(d))
    if issues: bad.append((r.run_id,issues))
print('integrity issues:',bad if bad else 'none')
