import re, subprocess
src = 'paper/paper_draft.md'
s = open(src).read()

def group(s, i):
    assert s[i] == '{', (i, s[i:i+20])
    d = 0
    for j in range(i, len(s)):
        if s[j] == '{':
            d += 1
        elif s[j] == '}':
            d -= 1
            if d == 0:
                return s[i+1:j], j+1
    raise ValueError('unbalanced')

def conv(s):
    out = []
    i = 0
    while i < len(s):
        if s.startswith('\\frac', i):
            i += 5
            while i < len(s) and s[i].isspace():
                i += 1
            n, i = group(s, i)
            while i < len(s) and s[i].isspace():
                i += 1
            d, i = group(s, i)
            out.append('(' + conv(n) + ')/(' + conv(d) + ')')
        elif s.startswith('\\overline', i):
            i += 9
            while i < len(s) and s[i].isspace():
                i += 1
            a, i = group(s, i)
            out.append('\\bar{' + conv(a) + '}')
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)

s2 = conv(s)
open('paper/paper_draft_docx.md', 'w').write(s2)
print('frac left:', s2.count('\\frac'), 'overline left:', s2.count('\\overline'))
subprocess.run(['pandoc', 'paper/paper_draft_docx.md', '--resource-path=paper',
                '-o', 'paper/paper_draft.docx'], check=True)
print('docx written')
